def is_all_nested_lists(lst):
    """
    Checks whether all elements in the provided list are lists, including nested ones.

    Parameters:
    lst (list): The list to check.

    Returns:
    bool: True if all elements are lists, including nested ones, False otherwise.
    """
    if not isinstance(lst, list):
        return False
    for element in lst:
        if not isinstance(element, list):
            return False
        if not is_all_nested_lists(element):
            return False
    return True
